INSERT INTO sources(title,publisher,url,publication_date,status,reviewed_at) VALUES ('Walmart FY2026 Form 10-K Exhibit 21 significant subsidiaries','Walmart Inc.','https://stock.walmart.com/sec-filings/all-sec-filings/content/0000104169-26-000055/wmtexhibit21fy26.htm','2026-03-13','approved',CURRENT_TIMESTAMP) ON CONFLICT(url) DO UPDATE SET title=excluded.title,publisher=excluded.publisher,publication_date=excluded.publication_date,status='approved',reviewed_at=CURRENT_TIMESTAMP;
INSERT INTO relationships(company_id,source_id,target_name,relationship_type,description,review_status) SELECT c.id,s.id,'Flipkart Private Limited','Majority-owned subsidiary','Walmart''s fiscal 2026 Exhibit 21 reports 84% equity ownership of Flipkart Private Limited (Singapore). The figure is equity ownership, not evidence of a specific payment or environmental wrongdoing.','approved' FROM companies c JOIN sources s ON s.url='https://stock.walmart.com/sec-filings/all-sec-filings/content/0000104169-26-000055/wmtexhibit21fy26.htm' WHERE c.slug='walmart' AND NOT EXISTS(SELECT 1 FROM relationships r WHERE r.company_id=c.id AND r.source_id=s.id AND r.target_name='Flipkart Private Limited' AND r.relationship_type='Majority-owned subsidiary');
INSERT INTO sources(title,publisher,url,publication_date,status,reviewed_at) VALUES ('Amazon 2025 Form 10-K equity investment risk disclosures','Amazon.com, Inc. / SEC','https://www.sec.gov/Archives/edgar/data/1018724/000101872426000004/amzn-20251231.htm','2026-02-06','approved',CURRENT_TIMESTAMP) ON CONFLICT(url) DO UPDATE SET title=excluded.title,publisher=excluded.publisher,publication_date=excluded.publication_date,status='approved',reviewed_at=CURRENT_TIMESTAMP;
INSERT INTO relationships(company_id,source_id,target_name,relationship_type,description,review_status) SELECT c.id,s.id,'Rivian Automotive, Inc.','Disclosed equity investment','Amazon''s 2025 Form 10-K identifies a publicly traded equity investment in Rivian; market value and valuation changes are not cash contributions or evidence of environmental harm.','approved' FROM companies c JOIN sources s ON s.url='https://www.sec.gov/Archives/edgar/data/1018724/000101872426000004/amzn-20251231.htm' WHERE c.slug='amazon' AND NOT EXISTS(SELECT 1 FROM relationships r WHERE r.company_id=c.id AND r.source_id=s.id AND r.target_name='Rivian Automotive, Inc.' AND r.relationship_type='Disclosed equity investment');
INSERT INTO relationships(company_id,source_id,target_name,relationship_type,description,review_status) SELECT c.id,s.id,'Anthropic PBC','Equity and convertible debt investment','Amazon''s 2025 Form 10-K describes equity and available-for-sale convertible debt investments relating to Anthropic; this records an investment relationship, not a claim of wrongdoing.','approved' FROM companies c JOIN sources s ON s.url='https://www.sec.gov/Archives/edgar/data/1018724/000101872426000004/amzn-20251231.htm' WHERE c.slug='amazon' AND NOT EXISTS(SELECT 1 FROM relationships r WHERE r.company_id=c.id AND r.source_id=s.id AND r.target_name='Anthropic PBC' AND r.relationship_type='Equity and convertible debt investment');
INSERT INTO sources(title,publisher,url,publication_date,status,reviewed_at) VALUES ('The Coca-Cola Company 2025 Form 10-K equity method investees','The Coca-Cola Company / SEC','https://investors.coca-colacompany.com/filings-reports/all-sec-filings/content/0001628280-26-010047/ko-20251231.htm','2026-02-20','approved',CURRENT_TIMESTAMP) ON CONFLICT(url) DO UPDATE SET title=excluded.title,publisher=excluded.publisher,publication_date=excluded.publication_date,status='approved',reviewed_at=CURRENT_TIMESTAMP;
INSERT INTO relationships(company_id,source_id,target_name,relationship_type,description,review_status) SELECT c.id,s.id,'Coca-Cola FEMSA, S.A.B. de C.V.','Equity method investment','Coca-Cola''s 2025 Form 10-K reports an approximately 28% ownership interest in Coca-Cola FEMSA as of December 31, 2025. This is an equity relationship, not evidence of a transfer of funds to an environmental activity.','approved' FROM companies c JOIN sources s ON s.url='https://investors.coca-colacompany.com/filings-reports/all-sec-filings/content/0001628280-26-010047/ko-20251231.htm' WHERE c.slug='coca-cola' AND NOT EXISTS(SELECT 1 FROM relationships r WHERE r.company_id=c.id AND r.source_id=s.id AND r.target_name='Coca-Cola FEMSA, S.A.B. de C.V.' AND r.relationship_type='Equity method investment');
